UTC = dt.timezone.utc  # noqa: UP017 (dt.UTC needs Python 3.11; macOS python3 is 3.9)
DEFAULT_LEARNED = """
## What we tried and learned

- (add one bullet per experiment: what changed, what happened, what we keep)
